    from ..exceptions import RequestedRangeNotSatisfiable

    if not self.data or self.content_length is None:
        raise ValueError("Response data and content length must be set before applying range.")

    if request.range is None:
        return

    if request.if_range and is_resource_modified(
        request.environ,
        etag=self.etag,
        last_modified=self.last_modified,
        ignore_if_range=False,
    ):
        return

    if request.range.units != 'bytes':
        raise RequestedRangeNotSatisfiable(self.content_length)

    if len(request.range.ranges) > 1:
        # Only the first range is used if multiple ranges are given
        request.range.ranges = request.range.ranges[:1]

    for start, stop in request.range.ranges:
        if stop is None:
            stop = self.content_length
        if start < 0 or stop > self.content_length or start >= stop:
            raise RequestedRangeNotSatisfiable(self.content_length)

        self.data = self.data[start:stop]
        self.content_length = stop - start
        self.status_code = 206
        self.content_range = f'bytes {start}-{stop-1}/{self.content_length}'
        self.headers['Content-Range'] = self.content_range
        break
